  for (const name of named) {
    let best = null;
    for (const declaration of occurrences(source, name)) {
      const statement = statementEnd(bytes, declaration);
      for (const region of regions.filter((candidate) => candidate.open >= declaration && candidate.close <= statement)) {
        const held = directMembers(literals, region.open).length;
        if (held === 0) continue;
        best = better(best, held, region);
      }
    }
    if (best) return best[2];
  }
  return null;
}

function better(best, held, region) {
  const span = Math.max(0, region.close - region.open);
  if (best && (best[0] > held || (best[0] === held && best[1] <= span))) return best;
  return [held, span, region];
}

function directMembers(literals, open) {
  return literals.filter((literal) => literal.enclosing === open);
}

const isWordCharacter = (character) => character !== undefined && (isAsciiAlphanumeric(character) || character === '_');

/** Mirrors `fn occurrences`: UTF-8 byte offsets just past each whole-word `name`. */
function occurrences(source, name) {
  const found = [];
  if (name === '') return found;
  let cursor = 0;
  for (let at = source.indexOf(name, cursor); at >= 0; at = source.indexOf(name, cursor)) {
    const end = at + name.length;
    const before = Array.from(source.slice(0, at)).pop();
    const after = Array.from(source.slice(end, end + 2))[0];
    if (!isWordCharacter(before) && !isWordCharacter(after)) found.push(encoder.encode(source.slice(0, end)).length);
    cursor = end;
  }
  return found;
}

const BYTE = Object.freeze({
  slash: 0x2f, star: 0x2a, quote: 0x22, apostrophe: 0x27, backslash: 0x5c, newline: 0x0a, semicolon: 0x3b,
});
const OPENERS = new Map([[0x5b, 0x5d], [0x28, 0x29], [0x7b, 0x7d]]);
const CLOSERS = new Set([0x5d, 0x29, 0x7d]);

function statementEnd(bytes, from) {
  let depth = 0;
  for (let index = from; index < bytes.length; index += 1) {
    const byte = bytes[index];
    if (OPENERS.has(byte)) depth += 1;
    else if (CLOSERS.has(byte)) depth = Math.max(0, depth - 1);
    else if (byte === BYTE.semicolon && depth === 0) return index;
    else if (byte === BYTE.newline && depth === 0 && bytes[index + 1] === BYTE.newline) return index;
  }
  return bytes.length;
}

function indexOfBytes(bytes, needle, from) {
  outer: for (let index = from; index + needle.length <= bytes.length; index += 1) {
    for (let at = 0; at < needle.length; at += 1) if (bytes[index + at] !== needle[at]) continue outer;
    return index;
  }
  return -1;
}

function scan(bytes) {
  const regions = [];
  const literals = [];
  const openStack = [];
  let index = 0;
  while (index < bytes.length) {
    const byte = bytes[index];
    if (byte === BYTE.slash && bytes[index + 1] === BYTE.slash) {
      const newline = bytes.indexOf(BYTE.newline, index);
      index = newline < 0 ? bytes.length : newline;
    } else if (byte === BYTE.slash && bytes[index + 1] === BYTE.star) {
      const close = indexOfBytes(bytes, [BYTE.star, BYTE.slash], index + 2);
      index = close < 0 ? bytes.length : close + 2;
    } else if (byte === BYTE.apostrophe) {
      index = charLiteralEnd(bytes, index);
    } else if (byte === BYTE.quote) {
      const closing = stringLiteralEnd(bytes, index);
      if (closing === null) {
        index += 1;
        continue;
      }
      literals.push({
        start: index,
        end: closing + 1,
        value: byteSlice(bytes, index + 1, closing) ?? '',
        enclosing: openStack.length ? openStack[openStack.length - 1][1] : null,
      });
      index = closing + 1;
    } else if (OPENERS.has(byte)) {
      openStack.push([byte, index]);
      index += 1;
    } else if (CLOSERS.has(byte)) {
      const opened = openStack.pop();
      if (opened && OPENERS.get(opened[0]) === byte) regions.push({ open: opened[1], close: index });
      index += 1;
    } else index += 1;
  }
  const byOpen = new Map();
  for (const region of regions) if (!byOpen.has(region.open)) byOpen.set(region.open, region);
  const unique = [...byOpen.values()].sort((a, b) => (a.open - b.open) || (a.close - b.close));
  literals.sort((a, b) => a.start - b.start);
  return [unique, literals];
}

function stringLiteralEnd(bytes, open) {
  let cursor = open + 1;
  while (cursor < bytes.length) {
    if (bytes[cursor] === BYTE.backslash) cursor += 2;
    else if (bytes[cursor] === BYTE.quote) return cursor;
    else if (bytes[cursor] === BYTE.newline) return null;
    else cursor += 1;
  }
  return null;
}

function charLiteralEnd(bytes, open) {
  for (const width of [2, 3]) {
    if (bytes[open + width] === BYTE.apostrophe) {
      const escaped = bytes[open + 1] === BYTE.backslash;
      if ((width === 2 && !escaped) || (width === 3 && escaped)) return open + width + 1;
    }
  }
  return open + 1;
}

function withoutSpans(text, spans) {
  let kept = '';
  let cursor = 0;
  for (const [start, end] of spans) {
    if (start < cursor) continue;
    kept += `${text.slice(cursor, start)} `;
    cursor = end;
  }
  return kept + text.slice(cursor);
}

function isMemberLiteral(value) {
  return value !== '' && encoder.encode(value).length <= MAX_MEMBER_LENGTH && !value.includes('"') && !value.includes('\\')
    && Array.from(value).every((character) => !isWhitespace(character) || character === ' ');
}

function looksLikeADeclaredName(token) {
  return validIdentifier(token) && token.length > 1
    && (token.includes('_') || !/[a-z]/.test(token) || (/[A-Z]/.test(token) && !/^[A-Z]/.test(token)));
}

function bareSourcePaths(task, literalSpans) {
  const paths = [];
  let cursor = 0;
  for (const [start, end] of [...literalSpans, [task.length, task.length]]) {
    if (cursor <= start) {
      for (const [offset, path] of prosePathTokens(task.slice(cursor, start))) paths.push([cursor + offset, path]);
    }
    cursor = Math.max(end, cursor);
  }
  return paths;
}

function prosePathTokens(prose) {
  const out = [];
  let start = 0;
  const chars = Array.from(prose);
  let chunk = '';
  const flush = () => {
    const isEdge = (character) => !isAsciiAlphanumeric(character) && !'_-./'.includes(character);
    const trimmed = trimMatches(chunk, isEdge);
    const token = trimEndMatches(trimmed, (character) => character === '.');
    if (isWorkspacePath(token)) {
      let lead = 0;
      while (lead < chunk.length && isEdge(chunk[lead])) lead += chunk.codePointAt(lead) > 0xffff ? 2 : 1;
      out.push([start + lead, token]);
    }
    start += chunk.length;
    chunk = '';
  };
  for (const character of chars) {
    chunk += character;
    if (isWhitespace(character) || character === ',') flush();
  }
  if (chunk !== '') flush();
  return out;
}

function isWorkspacePath(token) {
  const dot = token.lastIndexOf('.');
  if (dot < 0) return false;
  const stem = token.slice(0, dot);
  const extension = token.slice(dot + 1);
  return stem !== '' && !token.startsWith('/') && !token.split('/').some((component) => component === '..')
    && extension.length >= 1 && extension.length <= 8
    && /^[A-Za-z0-9]*$/.test(extension) && !Array.from(extension).every(isAsciiDigit)
    && /^[A-Za-z0-9_./-]*$/.test(token);
}

function validIdentifier(identifier) {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(identifier);
}

function readArguments(path) {
  return jsonText({ path, filePath: path, file_path: path });
}

changes.before:
//! Grounded structural edits over client-supplied workspace bytes.
//!
//! Unlike literal replacement, member insertion has no complete old value in the
//! request. The planner must read the target, derive the replacement from those
//! bytes, write the full updated source, and observe the result.
//!
//! Everything about *where* the insertion goes is discovered from the target's
//! own bytes rather than from the request's wording: which member list is meant,
//! which delimiters enclose it, which separator joins its members, and which of
//! the request's values are already there. The request only has to name a file,
//! say that a member list is involved, and quote the members. That is why one
//! recipe covers a bracketed array, a `matches!` alternation and a parenthesised
//! group without a branch per shape (#1069).

use std::collections::HashMap;

use serde_json::json;

use super::code_artifact::{latest_result, result_for_command, source_from_read_result};
use super::code_task::{render_seeded_change, render_seeded_outcome};
use super::planner::{AgenticPlan, Capability, plan_one, tool_for, write_arguments};
use crate::normal_markov::{quoted_segment_spans, unwrap_transport_quotes};
use crate::protocol::ChatMessage;
use crate::seed;

/// Longest member literal the route will write.
///
/// Member literals are short by nature. The bound is what keeps a quoted
/// *sentence* — prose the caller happened to quote — from being written into
/// source as if it were a member.
const MAX_MEMBER_LENGTH: usize = 96;

#[derive(Debug, Clone, PartialEq, Eq)]
struct MemberInsertion {
    target: String,
    /// Quoted member literals, in request order. Some are usually already in
    /// the file: those are the evidence that locates the list, and the rest are
    /// what gets inserted. Which is which is decided by reading the file.
    values: Vec<String>,
    /// Identifiers the request offered as names for the list, most explicit
    /// first. Only consulted when no quoted value occurs in the file.
    named: Vec<String>,
}

pub(super) fn plan_structured_edit_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
) -> Option<AgenticPlan> {
    let task = unwrap_transport_quotes(task);
    let edit = member_insertion(task)?;
    // A continuation cue resumes this run rather than opening a new request,
    // so the read, write, and verification evidence gathered for it must
    // survive the ping (issue #1138): slicing at the last user message -- the
    // cue itself -- restarted the read on every ping and the insertion never
    // advanced.
    let current_turn = &messages[super::planner::evidence_window_start(messages)..];
    let source = latest_result(current_turn, Capability::Read)
        .as_deref()
        .map(source_from_read_result)
        .filter(|source| !source.is_empty());

    let Some(source) = source else {
        let read_tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(read_tool, read_arguments(&edit.target)));
    };
    let (updated, inserted) = insert_members(&source, &edit)?;
    // A read that already lists every member is itself the observation: a run
    // resumed after a client compaction answers at once instead of spending
    // another full-file observation that pushes it over the threshold again.
    if inserted.is_empty() && latest_result(current_turn, Capability::Write).is_none() {
        return Some(AgenticPlan::Final(render_seeded_change(
            "coding_member_already_present",
            task,
            &edit.target,
            &[("{members}", &quoted_list(&edit.values))],
        )?));
    }

    // Members the file already lists need no write: after a client compaction
    // the run re-reads the file it already changed, and rewriting it in full
    // pushed the session straight back over the compaction threshold (the
    // issue #1028 ladder looped read -> write until its budget ran out).
    if !inserted.is_empty() && latest_result(current_turn, Capability::Write).is_none() {
        let write_tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            write_tool,
            write_arguments(&edit.target, &updated),
        ));
    }
    if let Some(observed) = result_for_command(current_turn, &format!("cat {}", edit.target)) {
        if super::tool_result::observed_bytes_match(&observed, &updated) {
            // Say what went in, not just that the file was written. The read
            // step is what made this knowable, and a caller that asked for a
            // record of the change -- the issue #1028 ladder does -- has
            // nothing to record when the answer is a status line.
            let (intent, change) = if inserted.is_empty() {
                ("coding_member_already_present", quoted_list(&edit.values))
            } else {
                ("coding_member_inserted", quoted_list(&inserted))
            };
            return Some(AgenticPlan::Final(render_seeded_change(
                intent,
                task,
                &edit.target,
                &[("{members}", &change)],
            )?));
        }
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &edit.target,
        )?));
    }
    let run_tool = tool_for(tool_names, Capability::Run)?;
    Some(plan_one(
        run_tool,
        json!({"command": format!("cat {}", edit.target)}).to_string(),
    ))
}

fn member_insertion(task: &str) -> Option<MemberInsertion> {
    // Seed matching is token-bounded. Collapse punctuation to token separators
    // so a concept at the end of a sentence (for example `array.`) remains
    // evidence for the same meaning without adding language-specific syntax.
    let normalized = task
        .to_lowercase()
        .split(|character: char| !character.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    let lexicon = seed::lexicon();
    let changes_a_file = lexicon.mentions_role(seed::ROLE_FILE_WRITE_ACTION_CUE, &normalized)
        || lexicon.mentions_role(seed::ROLE_FILE_EDIT_ACTION_CUE, &normalized);
    if !changes_a_file || !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_LIST_KIND, &normalized) {
        return None;
    }
    // The noun says a member list is in play; it does not say the request wants
    // one to grow. Issue #1131: a whole-file rewrite carried the bare word
    // `set` in `set -euo pipefail` and quoted two values in its explanation of
    // *why* the rewrite was needed. That was enough to route it here, and both
    // values were spliced into the script's nearest bracket -- a shell
    // condition -- which parses and is always true. An insertion has to be
    // asked for, so the verb is required evidence alongside the noun.
    if !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_ADD_ACTION, &normalized) {
        return None;
    }

    // A backtick slot is prose markup; a quotation slot is a literal. The
    // delimiter says what the slot is *for*, and the slot's own text says what
    // it *is*: a workspace path, a declared name, or a member value. Reading
    // both keeps `matches!` out of the values and a quoted `"target"` out of
    // the names, while letting a path be written either way -- which delimiter
    // a request wraps its target in is a spelling, not a different task.
    let mut values = Vec::new();
    let mut named = Vec::new();
    let mut candidates = Vec::new();
    let mut literal_target = None;
    let mut literal_spans = Vec::new();
    for segment in quoted_segment_spans(task) {
        let marked_up = task[segment.start..].starts_with('`');
        let path = is_workspace_path(&segment.text).then(|| segment.text.clone());
        if marked_up {
            if let Some(path) = path {
                candidates.push((segment.start, path));
            } else if valid_identifier(&segment.text) && !named.contains(&segment.text) {
                named.push(segment.text.clone());
            }
        } else if is_member_literal(&segment.text) {
            // A value quoted again (a ladder node's `result=` clause repeats
            // it) is still one member.
            if !values.contains(&segment.text) {
                values.push(segment.text.clone());
            }
            if literal_target.is_none() {
                literal_target = path;
            }
        }
        literal_spans.push((segment.start, segment.end));
    }
    if values.is_empty() {
        return None;
    }

    // The path and any bare identifier hints are read from the prose that is
    // left once the delimited slots are removed, so a quoted value can never be
    // mistaken for either. A quoted path is not a candidate at all, only a last
    // resort, because a quoted path is a member value first.
    let prose = without_spans(task, &literal_spans);
    candidates.extend(bare_source_paths(task, &literal_spans));

    // A request may name several files and change only one of them. The ladder
    // leaf prompts name three -- the source to edit, an effects record, and a
    // proof note -- and an earlier rule that read the first *undelimited* path
    // picked the proof note, because the file to edit was the one the prompt had
    // bothered to mark up. Preferring markup instead only moves the failure: a
    // request is free to mark up an incidental file and leave its target bare.
    //
    // What separates them is not the delimiter but the shape and the position.
    // A token carrying a `/` locates a file in the workspace; a bare basename
    // only mentions one, and a request that means to be acted on says where.
    // Among equals, the earliest wins, because a request states what it is
    // acting on before it says what to do afterwards.
    //
    // Ranked against labelled data by
    // `experiments/issue_1069_paths_in_prose/order-survey.py`, which replays
    // this repository's own commit messages -- change requests written after
    // the fact -- against the files each commit actually touched. Over the 418
    // messages that name two or more paths, taking the earliest names a changed
    // file 68.42% of the time, and preferring a workspace-relative one first
    // raises that to 84.67%; 29.19% of those messages open with a bare basename
    // before giving the path (`release.yml`, then
    // `.github/workflows/release.yml`). Taking the *latest* path is worse than
    // either at 63.64%. The proxy is loose -- a commit touches many files --
    // so it is used to rank the rules against each other, not as an accuracy
    // claim; the exact obligation is pinned instead by
    // `issue_1069_every_ladder_leaf_reaches_a_real_change`, which requires all
    // 32 ladder leaves to reach the file their contract names.
    candidates.sort_by_key(|(offset, path)| (!path.contains('/'), *offset));
    let mut target = candidates
        .into_iter()
        .next()
        .map(|(_, path)| path)
        .or(literal_target);
    // Issue #1085 (D2.2): a request that names behaviour and no file is
    // resolved through the self-AST census, the links network over the
    // workspace's own source.
    if target.is_none()
        && let Some(resolved) = super::requirement_resolution::resolve_requirement_target(task)
    {
        if !named.contains(&resolved.symbol) {
            named.push(resolved.symbol.clone());
        }
        target = Some(resolved.module_path);
    }
    let target = target?;
    for token in prose
        .replacen(&target, " ", 1)
        .split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
        .filter(|token| looks_like_a_declared_name(token))
    {
        let token = token.to_owned();
        if !named.contains(&token) {
            named.push(token);
        }
    }
    Some(MemberInsertion {
        target,
        values,
        named,
    })
}

/// A byte range of `source` enclosed by one matched delimiter pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Region {
    open: usize,
    close: usize,
}

/// A string literal in `source`, with the innermost region that encloses it.
#[derive(Debug, Clone)]
struct Literal {
    start: usize,
    end: usize,
    value: String,
    enclosing: Option<usize>,
}

/// The updated source, and the values this call put into the list.
///
/// The second half is what lets the route *state* its change instead of merely
/// reporting that a file was touched: which of the request's values were
/// missing is discovered from the target's bytes, so it is knowledge only this
/// function has. It is empty when the list already held everything asked for.
fn insert_members(source: &str, edit: &MemberInsertion) -> Option<(String, Vec<String>)> {
    // Issue #1085 (D2.1): a links-network substitution first; the byte path
    // below remains for shapes the rule file does not declare.
    if let Some(updated) = edit.named.first().and_then(|list| {
        super::link_edit_rules::insert_members_via_links(source, list, &edit.values)
    }) {
        return Some(updated);
    }
    let (regions, literals) = scan(source);
    let anchor = anchor_by_members(&regions, &literals, &edit.values)
        .or_else(|| anchor_by_name(source, &regions, &literals, &edit.named))?;
    let members = direct_members(&literals, anchor.open);
    let absent = edit
        .values
        .iter()
        .filter(|value| !members.iter().any(|member| &member.value == *value))
        .cloned()
        .collect::<Vec<_>>();
    if absent.is_empty() {
        // Everything asked for is already a member. Converging on the current
        // bytes keeps a retried task from duplicating its own earlier effect.
        return Some((source.to_owned(), absent));
    }
    let last = members.last()?;
    let separator = members
        .windows(2)
        .next_back()
        .and_then(|pair| source.get(pair[0].end..pair[1].start))
        .filter(|gap| !gap.is_empty())
        .unwrap_or(", ");
    let mut addition = String::new();
    for value in &absent {
        addition.push_str(separator);
        addition.push('"');
        addition.push_str(value);
        addition.push('"');
    }
    let mut updated = String::with_capacity(source.len() + addition.len());
    updated.push_str(source.get(..last.end)?);
    updated.push_str(&addition);
    updated.push_str(source.get(last.end..)?);
    Some((updated, absent))
}

/// Apply the existing member-list editor to one declaration selected by a
/// repository census.
///
/// This is the narrow bridge used by the repository workspace protocol. The
/// requirement still has to carry the registry-grounded edit/list/add intents,
/// and only quoted literal slots are eligible values. A locator-selected
/// declaration replaces the ambient-checkout target inference used by the
/// conversational route, so the same structural algorithm works in a clone.
#[must_use]
pub fn insert_quoted_members_into_named_list(
    source: &str,
    declaration: &str,
    requirement: &str,
) -> Option<(String, Vec<String>)> {
    let normalized = requirement
        .to_lowercase()
        .split(|character: char| !character.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    let lexicon = seed::lexicon();
    let changes_a_file = lexicon.mentions_role(seed::ROLE_FILE_WRITE_ACTION_CUE, &normalized)
        || lexicon.mentions_role(seed::ROLE_FILE_EDIT_ACTION_CUE, &normalized);
    if !changes_a_file
        || !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_LIST_KIND, &normalized)
        || !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_ADD_ACTION, &normalized)
    {
        return None;
    }
    let values = quoted_segment_spans(requirement)
        .into_iter()
        .filter(|segment| !requirement[segment.start..].starts_with('`'))
        .map(|segment| segment.text)
        .filter(|value| is_member_literal(value))
        .collect::<Vec<_>>();
    if values.is_empty() {
        return None;
    }
    insert_members(
        source,
        &MemberInsertion {
            target: String::new(),
            values,
            named: vec![declaration.to_owned()],
        },
    )
}

/// The members named the way the source spells them, for a sentence.
fn quoted_list(values: &[String]) -> String {
    values
        .iter()
        .map(|value| format!("\"{value}\""))
        .collect::<Vec<_>>()
        .join(", ")
}

/// The list the request is about is the one that already holds the members the
/// request named. The smallest such region wins, so a `matches!(subject, Some(
/// "a" | "b"))` resolves to the alternation rather than to the macro call that
/// contains it.
fn anchor_by_members(
    regions: &[Region],
    literals: &[Literal],
    values: &[String],
) -> Option<Region> {
    let mut best: Option<(usize, usize, Region)> = None;
    for region in regions {
        let members = direct_members(literals, region.open);
        let held = values
            .iter()
            .filter(|value| members.iter().any(|member| &member.value == *value))
            .count();
        if held == 0 {
            continue;
        }
        best = better(best, held, *region);
    }
    best.map(|(_, _, region)| region)
}

/// Nothing the request quoted is in the file yet, so fall back to the names it
/// offered. Within the statement that declares the name, the region holding the
/// most string literals is the value list — which is how `&[&str]` loses to
/// `&["a", "b"]` in `const NAMES: &[&str] = &["a", "b"];`.
fn anchor_by_name(
    source: &str,
    regions: &[Region],
    literals: &[Literal],
    named: &[String],
) -> Option<Region> {
    for name in named {
        let mut best: Option<(usize, usize, Region)> = None;
        for declaration in occurrences(source, name) {
            let statement = statement_end(source, declaration);
            for region in regions
                .iter()
                .filter(|region| region.open >= declaration && region.close <= statement)
            {
                let held = direct_members(literals, region.open).len();
                if held == 0 {
                    continue;
                }
                best = better(best, held, *region);
            }
        }
        if let Some((_, _, region)) = best {
            return Some(region);
        }
    }
    None
}

/// Prefer more matched members; break ties toward the tighter region.
const fn better(
    best: Option<(usize, usize, Region)>,
    held: usize,
    region: Region,
) -> Option<(usize, usize, Region)> {
    let span = region.close.saturating_sub(region.open);
    match best {
        Some((seen, tightest, _)) if seen > held || (seen == held && tightest <= span) => best,
        _ => Some((held, span, region)),
    }
}

fn direct_members(literals: &[Literal], open: usize) -> Vec<&Literal> {
    literals
        .iter()
        .filter(|literal| literal.enclosing == Some(open))
        .collect()
}

/// Byte offsets just past each whole-word occurrence of `name`.
fn occurrences(source: &str, name: &str) -> Vec<usize> {
    let mut found = Vec::new();
    let mut cursor = 0;
    while let Some(relative) = source.get(cursor..).and_then(|rest| rest.find(name)) {
        let at = cursor + relative;
        let end = at + name.len();
        let before_is_word = source[..at]
            .chars()
            .next_back()
            .is_some_and(|character| character.is_ascii_alphanumeric() || character == '_');
        let after_is_word = source[end..]
            .chars()
            .next()
            .is_some_and(|character| character.is_ascii_alphanumeric() || character == '_');
        if !before_is_word && !after_is_word {
            found.push(end);
        }
        cursor = end;
    }
    found
}

/// Where the declaration that starts at `from` stops: the first `;` written
/// outside any delimiter pair, or the first blank line, whichever comes first.
fn statement_end(source: &str, from: usize) -> usize {
    let bytes = source.as_bytes();
    let mut depth = 0usize;
    let mut index = from;
    while index < bytes.len() {
        match bytes[index] {
            b'[' | b'(' | b'{' => depth += 1,
            b']' | b')' | b'}' => depth = depth.saturating_sub(1),
            b';' if depth == 0 => return index,
            b'\n' if depth == 0 && source[index + 1..].starts_with('\n') => return index,
            _ => {}
        }
        index += 1;
    }
    bytes.len()
}

/// Collect every matched delimiter pair and every string literal, recording for
/// each literal the innermost pair that encloses it.
///
/// Literal bodies, line comments and block comments are skipped so a bracket
/// written inside one cannot open a region.
fn scan(source: &str) -> (Vec<Region>, Vec<Literal>) {
    let bytes = source.as_bytes();
    let mut regions = Vec::new();
    let mut literals = Vec::new();
    let mut open_stack: Vec<(u8, usize)> = Vec::new();
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'/' if bytes.get(index + 1) == Some(&b'/') => {
                index = source[index..]
                    .find('\n')
                    .map_or(bytes.len(), |offset| index + offset);
            }
            b'/' if bytes.get(index + 1) == Some(&b'*') => {
                index = source[index + 2..]
                    .find("*/")
                    .map_or(bytes.len(), |offset| index + 2 + offset + 2);
            }
            b'\'' => index = char_literal_end(bytes, index),
            b'"' => {
                let Some(closing) = string_literal_end(bytes, index) else {
                    index += 1;
                    continue;
                };
                literals.push(Literal {
                    start: index,
                    end: closing + 1,
                    value: source
                        .get(index + 1..closing)
                        .unwrap_or_default()
                        .to_owned(),
                    enclosing: open_stack.last().map(|(_, open)| *open),
                });
                index = closing + 1;
            }
            delimiter @ (b'[' | b'(' | b'{') => {
                open_stack.push((delimiter, index));
                index += 1;
            }
            delimiter @ (b']' | b')' | b'}') => {
                if let Some((opened, open)) = open_stack.pop()
                    && closing_delimiter(opened) == delimiter
                {
                    regions.push(Region { open, close: index });
                }
                index += 1;
            }
            _ => index += 1,
        }
    }
    // Regions close innermost-first; members read better in source order.
    let mut by_open: HashMap<usize, Region> = HashMap::new();
    for region in regions {
        by_open.entry(region.open).or_insert(region);
    }
    let mut regions = by_open.into_values().collect::<Vec<_>>();
    regions.sort_by_key(|region| (region.open, region.close));
    literals.sort_by_key(|literal| literal.start);
    (regions, literals)
}

const fn closing_delimiter(opened: u8) -> u8 {
    match opened {
        b'[' => b']',
        b'(' => b')',
        _ => b'}',
    }
}

const fn string_literal_end(bytes: &[u8], open: usize) -> Option<usize> {
    let mut cursor = open + 1;
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'\\' => cursor += 2,
            b'"' => return Some(cursor),
            // An unterminated literal is prose, not source: stop at the line.
            b'\n' => return None,
            _ => cursor += 1,
        }
    }
    None
}

/// `'a'` and `'\n'` are literals whose body must be skipped; `'static` is a
/// lifetime, and skipping it would swallow the rest of the line.
fn char_literal_end(bytes: &[u8], open: usize) -> usize {
    for width in [2, 3] {
        if bytes.get(open + width) == Some(&b'\'') {
            let escaped = bytes.get(open + 1) == Some(&b'\\');
            if (width == 2 && !escaped) || (width == 3 && escaped) {
                return open + width + 1;
            }
        }
    }
    open + 1
}

fn without_spans(text: &str, spans: &[(usize, usize)]) -> String {
    let mut kept = String::with_capacity(text.len());
    let mut cursor = 0;
    for &(start, end) in spans {
        if start < cursor {
            continue;
        }
        kept.push_str(text.get(cursor..start).unwrap_or_default());
        kept.push(' ');
        cursor = end;
    }
    kept.push_str(text.get(cursor..).unwrap_or_default());
    kept
}

/// A member literal is a short single-line phrase.
///
/// Spaces belong inside it. `experiments/issue_1069_member_shape/survey.py`
/// counts the string literals that sit directly inside a bracketed list in this
/// repository's own sources: 523 of 1738 (30.1%) hold whitespace, and 192 of
/// those carry a space at an edge because the list is scanned against prose --
/// `TARGET_MARKERS` holds `"to "` and `"into "` exactly so a scan cannot match
/// inside a longer word. Refusing whitespace refused nearly a third of every
/// member list in the tree, which is why `"Good morning"` could not be added to
/// `GREETING_EXAMPLES` (#1069).
///
/// What keeps a quoted *sentence* out is [`MAX_MEMBER_LENGTH`]; what keeps a
/// quoted code blob out is that a member never spans lines, which the survey
/// confirms -- only 6 of the 1738 do, and all six are `write!` fragments that
/// no request would ask to insert.
fn is_member_literal(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= MAX_MEMBER_LENGTH
        && !value.contains(['"', '\\'])
        && value
            .chars()
            .all(|character| !character.is_whitespace() || character == ' ')
}

/// A bare prose token only counts as the name of a declaration when it is
/// spelled the way declarations are and prose is not: `snake_case`, `SCREAMING`
/// or `camelCase`.
fn looks_like_a_declared_name(token: &str) -> bool {
    valid_identifier(token)
        && token.len() > 1
        && (token.contains('_')
            || token
                .chars()
                .all(|character| !character.is_ascii_lowercase())
            || (token
                .chars()
                .any(|character| character.is_ascii_uppercase())
                && !token.starts_with(|character: char| character.is_ascii_uppercase())))
}

/// Every undelimited workspace path in `task`, each with its byte offset in
/// `task`, skipping the delimited slots so a quoted member value is never read
/// as a path.
fn bare_source_paths(task: &str, literal_spans: &[(usize, usize)]) -> Vec<(usize, String)> {
    let mut paths = Vec::new();
    let mut cursor = 0;
    for (start, end) in literal_spans
        .iter()
        .copied()
        .chain(std::iter::once((task.len(), task.len())))
    {
        if let Some(gap) = task.get(cursor..start) {
            paths.extend(prose_path_tokens(gap).map(|(offset, path)| (cursor + offset, path)));
        }
        cursor = end.max(cursor);
    }
    paths
}

/// The workspace paths in a run of prose, in order, each with its byte offset.
fn prose_path_tokens(prose: &str) -> impl Iterator<Item = (usize, String)> + '_ {
    prose
        .split_inclusive(|character: char| character.is_whitespace() || character == ',')
        .scan(0_usize, |cursor, chunk| {
            let start = *cursor;
            *cursor += chunk.len();
            Some((start, chunk))
        })
        .filter_map(|(start, chunk)| {
            let trimmed = chunk.trim_matches(|character: char| {
                !character.is_ascii_alphanumeric() && !matches!(character, '_' | '-' | '.' | '/')
            });
            let token = trimmed.trim_end_matches('.');
            if !is_workspace_path(token) {
                return None;
            }
            let offset = start + (token.as_ptr() as usize - chunk.as_ptr() as usize);
            Some((offset, token.to_owned()))
        })
}

fn is_workspace_path(token: &str) -> bool {
    let Some((stem, extension)) = token.rsplit_once('.') else {
        return false;
    };
    !stem.is_empty()
        && !token.starts_with('/')
        && !token.split('/').any(|component| component == "..")
        && (1..=8).contains(&extension.len())
        && extension.chars().all(|character| character.is_ascii_alphanumeric())
        // A dotted run of digits is a number, not a file. Without this the
        // recursive ladder's own node id `1.1.2.2.1` reads as a path, and a
        // leaf prompt that names both `src/engine_responses.rs` and its node
        // sends the planner to open the node: the first real Agent CLI run of
        // that leaf opened with `File not found: .../1.1.2.2.1`, then, having
        // observed nothing, built an edit out of sentences from its own prompt.
        //
        // Measured rather than guessed, by
        // `experiments/issue_1069_dotted_tokens/survey.py`: across 15 782
        // tracked files and 67 distinct extensions, **no** tracked file has an
        // all-digit extension, while 12.77% of the dotted tokens this predicate
        // accepts in committed Markdown end in one -- 1 455 distinct spellings,
        // every one of them an IP address, a licence identifier, a version or a
        // section number (`127.0.0.1`, `Apache-2.0`, `0.1.0-beta.1`, `v1.22.0`),
        // and not one of them the name of a file this repository tracks.
        && !extension.chars().all(|character| character.is_ascii_digit())
        && token.chars().all(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '_' | '-' | '.' | '/')
        })
}

fn valid_identifier(identifier: &str) -> bool {
    let mut characters = identifier.chars();
    characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && characters.all(|character| character.is_ascii_alphanumeric() || character == '_')
}

fn read_arguments(path: &str) -> String {
    json!({"path": path, "filePath": path, "file_path": path}).to_string()
}

changes.expected:
//! Grounded structural edits over client-supplied workspace bytes.
//!
//! Unlike literal replacement, member insertion has no complete old value in the
//! request. The planner must read the target, derive the replacement from those
//! bytes, write the full updated source, and observe the result.
//!
//! Everything about *where* the insertion goes is discovered from the target's
//! own bytes rather than from the request's wording: which member list is meant,
//! which delimiters enclose it, which separator joins its members, and which of
//! the request's values are already there. The request only has to name a file,
//! say that a member list is involved, and quote the members. That is why one
//! recipe covers a bracketed array, a `matches!` alternation and a parenthesised
//! group without a branch per shape (#1069).

use std::collections::HashMap;

use serde_json::json;

use super::code_artifact::{latest_result, source_from_read_result};
use super::code_task::render_seeded_change;
use super::final_result::FinalResult;
use super::planner::{AgenticPlan, Capability, plan_one, tool_for, write_arguments};
use super::workspace_change::{VerifiedChange, plan_write_digest_verification};
use crate::normal_markov::{quoted_segment_spans, unwrap_transport_quotes};
use crate::protocol::ChatMessage;
use crate::seed;

/// Longest member literal the route will write.
///
/// Member literals are short by nature. The bound is what keeps a quoted
/// *sentence* — prose the caller happened to quote — from being written into
/// source as if it were a member.
const MAX_MEMBER_LENGTH: usize = 96;

#[derive(Debug, Clone, PartialEq, Eq)]
struct MemberInsertion {
    target: String,
    /// Quoted member literals, in request order. Some are usually already in
    /// the file: those are the evidence that locates the list, and the rest are
    /// what gets inserted. Which is which is decided by reading the file.
    values: Vec<String>,
    /// Identifiers the request offered as names for the list, most explicit
    /// first. Only consulted when no quoted value occurs in the file.
    named: Vec<String>,
}

pub(super) fn plan_structured_edit_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let task = unwrap_transport_quotes(task);
    let edit = member_insertion(task)?;
    // A continuation cue resumes this run rather than opening a new request,
    // so the read, write, and verification evidence gathered for it must
    // survive the ping (issue #1138): slicing at the last user message -- the
    // cue itself -- restarted the read on every ping and the insertion never
    // advanced.
    let current_turn = &messages[super::planner::evidence_window_start(messages)..];
    let source = latest_result(current_turn, Capability::Read)
        .as_deref()
        .map(source_from_read_result)
        .filter(|source| !source.is_empty());

    let Some(source) = source else {
        let read_tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(read_tool, read_arguments(&edit.target)));
    };
    let (updated, inserted) = insert_members(&source, &edit)?;
    // A read that already lists every member is itself the observation: a run
    // resumed after a client compaction answers at once instead of spending
    // another full-file observation that pushes it over the threshold again.
    if inserted.is_empty() && latest_result(current_turn, Capability::Write).is_none() {
        return Some(AgenticPlan::Final(render_seeded_change(
            "coding_member_already_present",
            task,
            &edit.target,
            &[("{members}", &quoted_list(&edit.values))],
        )?));
    }

    // Members the file already lists need no write: after a client compaction
    // the run re-reads the file it already changed, and rewriting it in full
    // pushed the session straight back over the compaction threshold (the
    // issue #1028 ladder looped read -> write until its budget ran out).
    if !inserted.is_empty() && latest_result(current_turn, Capability::Write).is_none() {
        let write_tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            write_tool,
            write_arguments(&edit.target, &updated),
        ));
    }
    let (intent, members) = if inserted.is_empty() {
        ("coding_member_already_present", quoted_list(&edit.values))
    } else {
        ("coding_member_inserted", quoted_list(&inserted))
    };
    plan_write_digest_verification(
        task,
        current_turn,
        tool_names,
        &VerifiedChange {
            target: &edit.target,
            expected: &updated,
            intent,
            slots: &[("{members}", members.as_str())],
            list_slots: &[],
        },
        result,
    )
}

fn member_insertion(task: &str) -> Option<MemberInsertion> {
    // Seed matching is token-bounded. Collapse punctuation to token separators
    // so a concept at the end of a sentence (for example `array.`) remains
    // evidence for the same meaning without adding language-specific syntax.
    let normalized = task
        .to_lowercase()
        .split(|character: char| !character.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    let lexicon = seed::lexicon();
    let changes_a_file = lexicon.mentions_role(seed::ROLE_FILE_WRITE_ACTION_CUE, &normalized)
        || lexicon.mentions_role(seed::ROLE_FILE_EDIT_ACTION_CUE, &normalized);
    if !changes_a_file || !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_LIST_KIND, &normalized) {
        return None;
    }
    // The noun says a member list is in play; it does not say the request wants
    // one to grow. Issue #1131: a whole-file rewrite carried the bare word
    // `set` in `set -euo pipefail` and quoted two values in its explanation of
    // *why* the rewrite was needed. That was enough to route it here, and both
    // values were spliced into the script's nearest bracket -- a shell
    // condition -- which parses and is always true. An insertion has to be
    // asked for, so the verb is required evidence alongside the noun.
    if !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_ADD_ACTION, &normalized) {
        return None;
    }

    // A backtick slot is prose markup; a quotation slot is a literal. The
    // delimiter says what the slot is *for*, and the slot's own text says what
    // it *is*: a workspace path, a declared name, or a member value. Reading
    // both keeps `matches!` out of the values and a quoted `"target"` out of
    // the names, while letting a path be written either way -- which delimiter
    // a request wraps its target in is a spelling, not a different task.
    let mut values = Vec::new();
    let mut named = Vec::new();
    let mut candidates = Vec::new();
    let mut literal_target = None;
    let mut literal_spans = Vec::new();
    for segment in quoted_segment_spans(task) {
        let marked_up = task[segment.start..].starts_with('`');
        let path = is_workspace_path(&segment.text).then(|| segment.text.clone());
        if marked_up {
            if let Some(path) = path {
                candidates.push((segment.start, path));
            } else if valid_identifier(&segment.text) && !named.contains(&segment.text) {
                named.push(segment.text.clone());
            }
        } else if is_member_literal(&segment.text) {
            // A value quoted again (a ladder node's `result=` clause repeats
            // it) is still one member.
            if !values.contains(&segment.text) {
                values.push(segment.text.clone());
            }
            if literal_target.is_none() {
                literal_target = path;
            }
        }
        literal_spans.push((segment.start, segment.end));
    }
    if values.is_empty() {
        return None;
    }

    // The path and any bare identifier hints are read from the prose that is
    // left once the delimited slots are removed, so a quoted value can never be
    // mistaken for either. A quoted path is not a candidate at all, only a last
    // resort, because a quoted path is a member value first.
    let prose = without_spans(task, &literal_spans);
    candidates.extend(bare_source_paths(task, &literal_spans));

    // A request may name several files and change only one of them. The ladder
    // leaf prompts name three -- the source to edit, an effects record, and a
    // proof note -- and an earlier rule that read the first *undelimited* path
    // picked the proof note, because the file to edit was the one the prompt had
    // bothered to mark up. Preferring markup instead only moves the failure: a
    // request is free to mark up an incidental file and leave its target bare.
    //
    // What separates them is not the delimiter but the shape and the position.
    // A token carrying a `/` locates a file in the workspace; a bare basename
    // only mentions one, and a request that means to be acted on says where.
    // Among equals, the earliest wins, because a request states what it is
    // acting on before it says what to do afterwards.
    //
    // Ranked against labelled data by
    // `experiments/issue_1069_paths_in_prose/order-survey.py`, which replays
    // this repository's own commit messages -- change requests written after
    // the fact -- against the files each commit actually touched. Over the 418
    // messages that name two or more paths, taking the earliest names a changed
    // file 68.42% of the time, and preferring a workspace-relative one first
    // raises that to 84.67%; 29.19% of those messages open with a bare basename
    // before giving the path (`release.yml`, then
    // `.github/workflows/release.yml`). Taking the *latest* path is worse than
    // either at 63.64%. The proxy is loose -- a commit touches many files --
    // so it is used to rank the rules against each other, not as an accuracy
    // claim; the exact obligation is pinned instead by
    // `issue_1069_every_ladder_leaf_reaches_a_real_change`, which requires all
    // 32 ladder leaves to reach the file their contract names.
    candidates.sort_by_key(|(offset, path)| (!path.contains('/'), *offset));
    let mut target = candidates
        .into_iter()
        .next()
        .map(|(_, path)| path)
        .or(literal_target);
    // Issue #1085 (D2.2): a request that names behaviour and no file is
    // resolved through the self-AST census, the links network over the
    // workspace's own source.
    if target.is_none()
        && let Some(resolved) = super::requirement_resolution::resolve_requirement_target(task)
    {
        if !named.contains(&resolved.symbol) {
            named.push(resolved.symbol.clone());
        }
        target = Some(resolved.module_path);
    }
    let target = target?;
    for token in prose
        .replacen(&target, " ", 1)
        .split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
        .filter(|token| looks_like_a_declared_name(token))
    {
        let token = token.to_owned();
        if !named.contains(&token) {
            named.push(token);
        }
    }
    Some(MemberInsertion {
        target,
        values,
        named,
    })
}

/// A byte range of `source` enclosed by one matched delimiter pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Region {
    open: usize,
    close: usize,
}

/// A string literal in `source`, with the innermost region that encloses it.
#[derive(Debug, Clone)]
struct Literal {
    start: usize,
    end: usize,
    value: String,
    enclosing: Option<usize>,
}

/// The updated source, and the values this call put into the list.
///
/// The second half is what lets the route *state* its change instead of merely
/// reporting that a file was touched: which of the request's values were
/// missing is discovered from the target's bytes, so it is knowledge only this
/// function has. It is empty when the list already held everything asked for.
fn insert_members(source: &str, edit: &MemberInsertion) -> Option<(String, Vec<String>)> {
    // Issue #1085 (D2.1): a links-network substitution first; the byte path
    // below remains for shapes the rule file does not declare.
    if let Some(updated) = edit.named.first().and_then(|list| {
        super::link_edit_rules::insert_members_via_links(source, list, &edit.values)
    }) {
        return Some(updated);
    }
    let (regions, literals) = scan(source);
    let anchor = anchor_by_members(&regions, &literals, &edit.values)
        .or_else(|| anchor_by_name(source, &regions, &literals, &edit.named))?;
    let members = direct_members(&literals, anchor.open);
    let absent = edit
        .values
        .iter()
        .filter(|value| !members.iter().any(|member| &member.value == *value))
        .cloned()
        .collect::<Vec<_>>();
    if absent.is_empty() {
        // Everything asked for is already a member. Converging on the current
        // bytes keeps a retried task from duplicating its own earlier effect.
        return Some((source.to_owned(), absent));
    }
    let last = members.last()?;
    let separator = members
        .windows(2)
        .next_back()
        .and_then(|pair| source.get(pair[0].end..pair[1].start))
        .filter(|gap| !gap.is_empty())
        .unwrap_or(", ");
    let mut addition = String::new();
    for value in &absent {
        addition.push_str(separator);
        addition.push('"');
        addition.push_str(value);
        addition.push('"');
    }
    let mut updated = String::with_capacity(source.len() + addition.len());
    updated.push_str(source.get(..last.end)?);
    updated.push_str(&addition);
    updated.push_str(source.get(last.end..)?);
    Some((updated, absent))
}

/// Apply the existing member-list editor to one declaration selected by a
/// repository census.
///
/// This is the narrow bridge used by the repository workspace protocol. The
/// requirement still has to carry the registry-grounded edit/list/add intents,
/// and only quoted literal slots are eligible values. A locator-selected
/// declaration replaces the ambient-checkout target inference used by the
/// conversational route, so the same structural algorithm works in a clone.
#[must_use]
pub fn insert_quoted_members_into_named_list(
    source: &str,
    declaration: &str,
    requirement: &str,
) -> Option<(String, Vec<String>)> {
    let normalized = requirement
        .to_lowercase()
        .split(|character: char| !character.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    let lexicon = seed::lexicon();
    let changes_a_file = lexicon.mentions_role(seed::ROLE_FILE_WRITE_ACTION_CUE, &normalized)
        || lexicon.mentions_role(seed::ROLE_FILE_EDIT_ACTION_CUE, &normalized);
    if !changes_a_file
        || !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_LIST_KIND, &normalized)
        || !lexicon.mentions_role(seed::ROLE_CODING_MEMBER_ADD_ACTION, &normalized)
    {
        return None;
    }
    let values = quoted_segment_spans(requirement)
        .into_iter()
        .filter(|segment| !requirement[segment.start..].starts_with('`'))
        .map(|segment| segment.text)
        .filter(|value| is_member_literal(value))
        .collect::<Vec<_>>();
    if values.is_empty() {
        return None;
    }
    insert_members(
        source,
        &MemberInsertion {
            target: String::new(),
            values,
            named: vec![declaration.to_owned()],
        },
    )
}

/// The members named the way the source spells them, for a sentence.
fn quoted_list(values: &[String]) -> String {
    values
        .iter()
        .map(|value| format!("\"{value}\""))
        .collect::<Vec<_>>()
        .join(", ")
}

/// The list the request is about is the one that already holds the members the
/// request named. The smallest such region wins, so a `matches!(subject, Some(
/// "a" | "b"))` resolves to the alternation rather than to the macro call that
/// contains it.
fn anchor_by_members(
    regions: &[Region],
    literals: &[Literal],
    values: &[String],
) -> Option<Region> {
    let mut best: Option<(usize, usize, Region)> = None;
    for region in regions {
        let members = direct_members(literals, region.open);
        let held = values
            .iter()
            .filter(|value| members.iter().any(|member| &member.value == *value))
            .count();
        if held == 0 {
            continue;
        }
        best = better(best, held, *region);
    }
    best.map(|(_, _, region)| region)
}

/// Nothing the request quoted is in the file yet, so fall back to the names it
/// offered. Within the statement that declares the name, the region holding the
/// most string literals is the value list — which is how `&[&str]` loses to
/// `&["a", "b"]` in `const NAMES: &[&str] = &["a", "b"];`.
fn anchor_by_name(
    source: &str,
    regions: &[Region],
    literals: &[Literal],
    named: &[String],
) -> Option<Region> {
    for name in named {
        let mut best: Option<(usize, usize, Region)> = None;
        for declaration in occurrences(source, name) {
            let statement = statement_end(source, declaration);
            for region in regions
                .iter()
                .filter(|region| region.open >= declaration && region.close <= statement)
            {
                let held = direct_members(literals, region.open).len();
                if held == 0 {
                    continue;
                }
                best = better(best, held, *region);
            }
        }
        if let Some((_, _, region)) = best {
            return Some(region);
        }
    }
    None
}

/// Prefer more matched members; break ties toward the tighter region.
const fn better(
    best: Option<(usize, usize, Region)>,
    held: usize,
    region: Region,
) -> Option<(usize, usize, Region)> {
    let span = region.close.saturating_sub(region.open);
    match best {
        Some((seen, tightest, _)) if seen > held || (seen == held && tightest <= span) => best,
        _ => Some((held, span, region)),
    }
}

fn direct_members(literals: &[Literal], open: usize) -> Vec<&Literal> {
    literals
        .iter()
        .filter(|literal| literal.enclosing == Some(open))
        .collect()
}

/// Byte offsets just past each whole-word occurrence of `name`.
fn occurrences(source: &str, name: &str) -> Vec<usize> {
    let mut found = Vec::new();
    let mut cursor = 0;
    while let Some(relative) = source.get(cursor..).and_then(|rest| rest.find(name)) {
        let at = cursor + relative;
        let end = at + name.len();
        let before_is_word = source[..at]
            .chars()
            .next_back()
            .is_some_and(|character| character.is_ascii_alphanumeric() || character == '_');
        let after_is_word = source[end..]
            .chars()
            .next()
            .is_some_and(|character| character.is_ascii_alphanumeric() || character == '_');
        if !before_is_word && !after_is_word {
            found.push(end);
        }
        cursor = end;
    }
    found
}

/// Where the declaration that starts at `from` stops: the first `;` written
/// outside any delimiter pair, or the first blank line, whichever comes first.
fn statement_end(source: &str, from: usize) -> usize {
    let bytes = source.as_bytes();
    let mut depth = 0usize;
    let mut index = from;
    while index < bytes.len() {
        match bytes[index] {
            b'[' | b'(' | b'{' => depth += 1,
            b']' | b')' | b'}' => depth = depth.saturating_sub(1),
            b';' if depth == 0 => return index,
            b'\n' if depth == 0 && source[index + 1..].starts_with('\n') => return index,
            _ => {}
        }
        index += 1;
    }
    bytes.len()
}

/// Collect every matched delimiter pair and every string literal, recording for
/// each literal the innermost pair that encloses it.
///
/// Literal bodies, line comments and block comments are skipped so a bracket
/// written inside one cannot open a region.
fn scan(source: &str) -> (Vec<Region>, Vec<Literal>) {
    let bytes = source.as_bytes();
    let mut regions = Vec::new();
    let mut literals = Vec::new();
    let mut open_stack: Vec<(u8, usize)> = Vec::new();
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'/' if bytes.get(index + 1) == Some(&b'/') => {
                index = source[index..]
                    .find('\n')
                    .map_or(bytes.len(), |offset| index + offset);
            }
            b'/' if bytes.get(index + 1) == Some(&b'*') => {
                index = source[index + 2..]
                    .find("*/")
                    .map_or(bytes.len(), |offset| index + 2 + offset + 2);
            }
            b'\'' => index = char_literal_end(bytes, index),
            b'"' => {
                let Some(closing) = string_literal_end(bytes, index) else {
                    index += 1;
                    continue;
                };
                literals.push(Literal {
                    start: index,
                    end: closing + 1,
                    value: source
                        .get(index + 1..closing)
                        .unwrap_or_default()
                        .to_owned(),
                    enclosing: open_stack.last().map(|(_, open)| *open),
                });
                index = closing + 1;
            }
            delimiter @ (b'[' | b'(' | b'{') => {
                open_stack.push((delimiter, index));
                index += 1;
            }
            delimiter @ (b']' | b')' | b'}') => {
                if let Some((opened, open)) = open_stack.pop()
                    && closing_delimiter(opened) == delimiter
                {
                    regions.push(Region { open, close: index });
                }
                index += 1;
            }
            _ => index += 1,
        }
    }
    // Regions close innermost-first; members read better in source order.
    let mut by_open: HashMap<usize, Region> = HashMap::new();
    for region in regions {
        by_open.entry(region.open).or_insert(region);
    }
    let mut regions = by_open.into_values().collect::<Vec<_>>();
    regions.sort_by_key(|region| (region.open, region.close));
    literals.sort_by_key(|literal| literal.start);
    (regions, literals)
}

const fn closing_delimiter(opened: u8) -> u8 {
    match opened {
        b'[' => b']',
        b'(' => b')',
        _ => b'}',
    }
}

const fn string_literal_end(bytes: &[u8], open: usize) -> Option<usize> {
    let mut cursor = open + 1;
    while cursor < bytes.len() {
        match bytes[cursor] {
            b'\\' => cursor += 2,
            b'"' => return Some(cursor),
            // An unterminated literal is prose, not source: stop at the line.
            b'\n' => return None,
            _ => cursor += 1,
        }
    }
    None
}

/// `'a'` and `'\n'` are literals whose body must be skipped; `'static` is a
/// lifetime, and skipping it would swallow the rest of the line.
fn char_literal_end(bytes: &[u8], open: usize) -> usize {
    for width in [2, 3] {
        if bytes.get(open + width) == Some(&b'\'') {
            let escaped = bytes.get(open + 1) == Some(&b'\\');
            if (width == 2 && !escaped) || (width == 3 && escaped) {
                return open + width + 1;
            }
        }
    }
    open + 1
}

fn without_spans(text: &str, spans: &[(usize, usize)]) -> String {
    let mut kept = String::with_capacity(text.len());
    let mut cursor = 0;
    for &(start, end) in spans {
        if start < cursor {
            continue;
        }
        kept.push_str(text.get(cursor..start).unwrap_or_default());
        kept.push(' ');
        cursor = end;
    }
    kept.push_str(text.get(cursor..).unwrap_or_default());
    kept
}

/// A member literal is a short single-line phrase.
///
/// Spaces belong inside it. `experiments/issue_1069_member_shape/survey.py`
/// counts the string literals that sit directly inside a bracketed list in this
/// repository's own sources: 523 of 1738 (30.1%) hold whitespace, and 192 of
/// those carry a space at an edge because the list is scanned against prose --
/// `TARGET_MARKERS` holds `"to "` and `"into "` exactly so a scan cannot match
/// inside a longer word. Refusing whitespace refused nearly a third of every
/// member list in the tree, which is why `"Good morning"` could not be added to
/// `GREETING_EXAMPLES` (#1069).
///
/// What keeps a quoted *sentence* out is [`MAX_MEMBER_LENGTH`]; what keeps a
/// quoted code blob out is that a member never spans lines, which the survey
/// confirms -- only 6 of the 1738 do, and all six are `write!` fragments that
/// no request would ask to insert.
fn is_member_literal(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= MAX_MEMBER_LENGTH
        && !value.contains(['"', '\\'])
        && value
            .chars()
            .all(|character| !character.is_whitespace() || character == ' ')
}

/// A bare prose token only counts as the name of a declaration when it is
/// spelled the way declarations are and prose is not: `snake_case`, `SCREAMING`
/// or `camelCase`.
fn looks_like_a_declared_name(token: &str) -> bool {
    valid_identifier(token)
        && token.len() > 1
        && (token.contains('_')
            || token
                .chars()
                .all(|character| !character.is_ascii_lowercase())
            || (token
                .chars()
                .any(|character| character.is_ascii_uppercase())
                && !token.starts_with(|character: char| character.is_ascii_uppercase())))
}

/// Every undelimited workspace path in `task`, each with its byte offset in
/// `task`, skipping the delimited slots so a quoted member value is never read
/// as a path.
fn bare_source_paths(task: &str, literal_spans: &[(usize, usize)]) -> Vec<(usize, String)> {
    let mut paths = Vec::new();
    let mut cursor = 0;
    for (start, end) in literal_spans
        .iter()
        .copied()
        .chain(std::iter::once((task.len(), task.len())))
    {
        if let Some(gap) = task.get(cursor..start) {
            paths.extend(prose_path_tokens(gap).map(|(offset, path)| (cursor + offset, path)));
        }
        cursor = end.max(cursor);
    }
    paths
}

/// The workspace paths in a run of prose, in order, each with its byte offset.
fn prose_path_tokens(prose: &str) -> impl Iterator<Item = (usize, String)> + '_ {
    prose
        .split_inclusive(|character: char| character.is_whitespace() || character == ',')
        .scan(0_usize, |cursor, chunk| {
            let start = *cursor;
            *cursor += chunk.len();
            Some((start, chunk))
        })
        .filter_map(|(start, chunk)| {
            let trimmed = chunk.trim_matches(|character: char| {
                !character.is_ascii_alphanumeric() && !matches!(character, '_' | '-' | '.' | '/')
            });
            let token = trimmed.trim_end_matches('.');
            if !is_workspace_path(token) {
                return None;
            }
            let offset = start + (token.as_ptr() as usize - chunk.as_ptr() as usize);
            Some((offset, token.to_owned()))
        })
}

fn is_workspace_path(token: &str) -> bool {
    let Some((stem, extension)) = token.rsplit_once('.') else {
        return false;
    };
    !stem.is_empty()
        && !token.starts_with('/')
        && !token.split('/').any(|component| component == "..")
        && (1..=8).contains(&extension.len())
        && extension.chars().all(|character| character.is_ascii_alphanumeric())
        // A dotted run of digits is a number, not a file. Without this the
        // recursive ladder's own node id `1.1.2.2.1` reads as a path, and a
        // leaf prompt that names both `src/engine_responses.rs` and its node
        // sends the planner to open the node: the first real Agent CLI run of
        // that leaf opened with `File not found: .../1.1.2.2.1`, then, having
        // observed nothing, built an edit out of sentences from its own prompt.
        //
        // Measured rather than guessed, by
        // `experiments/issue_1069_dotted_tokens/survey.py`: across 15 782
        // tracked files and 67 distinct extensions, **no** tracked file has an
        // all-digit extension, while 12.77% of the dotted tokens this predicate
        // accepts in committed Markdown end in one -- 1 455 distinct spellings,
        // every one of them an IP address, a licence identifier, a version or a
        // section number (`127.0.0.1`, `Apache-2.0`, `0.1.0-beta.1`, `v1.22.0`),
        // and not one of them the name of a file this repository tracks.
        && !extension.chars().all(|character| character.is_ascii_digit())
        && token.chars().all(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '_' | '-' | '.' | '/')
        })
}

fn valid_identifier(identifier: &str) -> bool {
    let mut characters = identifier.chars();
    characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && characters.all(|character| character.is_ascii_alphanumeric() || character == '_')
}

fn read_arguments(path: &str) -> String {
    json!({"path": path, "filePath": path, "file_path": path}).to_string()
}

changes.before:
//! Grounded, verified workspace transformations learned from coding-task runs.
//!
//! The planner never edits request prose. It compiles a bounded transformation,
//! reads the client-owned bytes, executes the transformation in memory, applies
//! a compact edit or bounded replace-all operation, and accepts success only
//! after an exact content-digest observation. The same state machine composes
//! source creation with a second module-registration edit, so a multi-file
//! request cannot stop after its first observable effect.

mod digest_verification;
pub(super) use digest_verification::plan_digest_verification;
use digest_verification::plan_write_digest_verification;

use serde_json::{Value, json};
use std::path::Path;

use super::code_artifact::source_from_read_result;
use super::code_task::{
    render_rust_template, render_seeded_change, render_seeded_outcome, rust_source_for_task,
};
use super::final_result::{FinalDisposition, FinalResult, record};
use super::general_planner::compose_edit_request;
use super::intent_router::edit_arguments;
use super::planner::{
    AgenticPlan, Capability, plan_one, tool_capability, tool_for, write_arguments,
};
use super::positional_edit::PositionalInsert;
use crate::normal_markov::{quoted_segments, unwrap_transport_quotes};
use crate::protocol::ChatMessage;
use crate::seed;
use crate::workspace_change_learning::{
    RewriteScope, execute_scoped_workspace_rewrite, is_identifier_word, word_scoped_matches,
};

#[derive(Debug, Clone, PartialEq, Eq)]
struct GroundedRewrite {
    target: String,
    pattern: String,
    replacement: String,
    /// How the pattern is allowed to match. Renaming an identifier is a
    /// word-scoped edit; replacing a quoted literal is a substring one -- or a
    /// word-scoped one when the new word contains the old (`smal` → `small`).
    scope: RewriteScope,
    /// Whether the request renamed a name (a word-scoped rename).
    renaming: bool,
    /// Whether the pattern must occur exactly once (a positional insertion's
    /// anchor), replaced once rather than everywhere.
    unique: bool,
    /// Whether the replacement holds the pattern, so it is applied in one
    /// pass rather than rewritten until no pattern is left (PR #1188 G78).
    single_pass: bool,
    /// The seed sentence that states the change, when it is not the
    /// rename/replace one (a positional insertion's).
    stated: Option<(&'static str, Vec<(&'static str, String)>)>,
    /// The pattern and replacement as the request wrote them, when it wrote
    /// `\n` / `\t` escapes the rewrite unescaped (see [`as_written`]).
    verbatim: Option<(String, String)>,
}

/// The template slots the seed sentences that state a rewrite fill.
const OLD_SLOT: &str = concat!("{", "old", "}");
const NEW_SLOT: &str = concat!("{", "new", "}");
const ANCHOR_SLOT: &str = concat!("{", "anchor", "}");

impl GroundedRewrite {
    /// The intent whose seed sentence states this change rather than merely
    /// reporting that the file was touched.
    const fn stated_intent(&self) -> &'static str {
        match self.stated {
            Some((intent, _)) => intent,
            None if self.renaming => "coding_identifier_renamed",
            None => "coding_text_replaced",
        }
    }

    /// The operands the seed sentence names, as template slots.
    fn stated_slots(&self) -> Vec<(&str, &str)> {
        match &self.stated {
            Some((_, slots)) => slots
                .iter()
                .map(|(slot, value)| (*slot, value.as_str()))
                .collect(),
            None => vec![
                (OLD_SLOT, self.pattern.as_str()),
                (NEW_SLOT, self.replacement.as_str()),
            ],
        }
    }
}

/// A change whose bytes are settled, awaiting the observation that confirms it.
///
/// `expected` is what the workspace should now hold; `intent` and `slots` are
/// the seed sentence that states the change once it does.
pub(super) struct VerifiedChange<'a> {
    pub(super) target: &'a str,
    pub(super) expected: &'a str,
    pub(super) intent: &'a str,
    pub(super) slots: &'a [(&'a str, &'a str)],
    pub(super) list_slots: &'a [(&'a str, &'a [String])],
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CompositeModuleChange {
    source_path: String,
    source: String,
    registration_path: String,
    registration: String,
}

pub(super) fn plan_workspace_change_step(
    task: &str,
    messages: &[ChatMessage],
    tool_names: &[&str],
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let task = unwrap_transport_quotes(task);
    // A continuation cue resumes this run rather than opening a new request,
    // so the read and write evidence gathered for it must survive the ping
    // (issue #1138): slicing at the last user message -- the cue itself --
    // restarted the read--write pair on every ping.
    let current_turn = &messages[super::planner::evidence_window_start(messages)..];
    // `Append the contents of a.txt to b.txt`: the source is read, and the
    // request is restated with its lines as the block placed (PR #1188 G50).
    let sourced = match sourced_request(task, current_turn) {
        Some(Sourced::Read(path)) => {
            let tool = tool_for(tool_names, Capability::Read)?;
            return Some(plan_one(tool, read_arguments(&path)));
        }
        Some(Sourced::Task(sourced)) => Some(sourced),
        None => None,
    };
    let task = sourced.as_deref().unwrap_or(task);

    if let Some(change) = composite_module_change(task) {
        return plan_composite_step(task, current_turn, tool_names, &change, result);
    }
    // Numbered lines moved to another file: placed there, then removed (G85).
    if let Some(order) = super::line_range_move::line_range_move(task) {
        return super::line_range_move::plan_line_range_move_step(
            task,
            current_turn,
            tool_names,
            &order,
            result,
        );
    }
    if let Some(change) = super::workspace_computed_change::grounded_line_change(task) {
        return super::workspace_computed_change::plan_computed_change_step(
            task,
            current_turn,
            tool_names,
            &change,
            result,
        );
    }
    if let Some(inserts) = insert_sequence(task) {
        return super::positional_edit::plan_insert_sequence_step(
            task,
            current_turn,
            tool_names,
            &inserts,
            result,
        );
    }
    // Several replacements asked in one sentence are made in order (G82).
    if let Some(change) = super::workspace_computed_change::grounded_replace_list(task) {
        return super::workspace_computed_change::plan_computed_change_step(
            task,
            current_turn,
            tool_names,
            &change,
            result,
        );
    }
    if let Some(rewrite) = grounded_rewrite(task) {
        return plan_rewrite_step(task, current_turn, tool_names, &rewrite, result);
    }
    let change = super::workspace_computed_change::grounded_computed_change(task)?;
    super::workspace_computed_change::plan_computed_change_step(
        task,
        current_turn,
        tool_names,
        &change,
        result,
    )
}

/// A request whose additive edit places another file's contents: the source
/// to read first, or the request restated with its lines.
enum Sourced {
    Read(String),
    Task(String),
}

/// `None` unless the request names a contents source and, restated, is an
/// additive edit the composers place.
fn sourced_request(task: &str, current_turn: &[ChatMessage]) -> Option<Sourced> {
    use super::contents_source::{contents_source, with_contents};
    let source = contents_source(task)?;
    let probe = with_contents(task, &source, "x");
    if insert_sequence(&probe).is_none()
        && super::workspace_computed_change::grounded_end_insertion(&probe).is_none()
    {
        return None;
    }
    let Some(read) = result_for_path(current_turn, Capability::Read, &source.path, None) else {
        return Some(Sourced::Read(source.path));
    };
    if super::code_artifact::source_from_agent_read_result(&read).is_none()
        && super::tool_result::failure_message(&read, false, true).is_some()
    {
        return None;
    }
    let contents = source_from_read_result(&read);
    Some(Sourced::Task(with_contents(task, &source, &contents)))
}

fn plan_rewrite_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    rewrite: &GroundedRewrite,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    let Some(read) = result_for_path(current_turn, Capability::Read, &rewrite.target, None) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(&rewrite.target)));
    };
    let source = source_from_read_result(&read);
    let written = as_written(&source, rewrite);
    let rewrite = written.as_ref().unwrap_or(rewrite);
    let Some(updated) = rewritten_source(&source, rewrite) else {
        // A replace asked again finds its old text gone: that is the answer (G87).
        let absent = super::replace_list::absent_text_answer(
            task,
            &rewrite.target,
            &source,
            &rewrite.pattern,
            Some(&rewrite.replacement),
        );
        return Some(AgenticPlan::Final(match absent {
            Some(answer) => answer,
            None => render_seeded_outcome(
                "coding_workspace_verification_failed",
                task,
                &rewrite.target,
            )?,
        }));
    };

    let occurrences = match rewrite.scope {
        RewriteScope::Substring => source.match_indices(&rewrite.pattern).count(),
        RewriteScope::Word => word_scoped_matches(&source, &rewrite.pattern).len(),
    };
    if occurrences > 1
        && let Some(answer) = super::edit_scope::scoped_decline(task, &rewrite.target, &source)
    {
        return Some(AgenticPlan::Final(answer));
    }
    if occurrences == 1 {
        // The bare pattern when it is unique in the file; otherwise the
        // smallest unique run of changed lines -- the edit tool refuses an
        // `oldString` it finds twice, and `smal` also sits inside `small`.
        let edit = if rewrite.unique {
            anchored_lines(&source, rewrite).map(|(_, old, new)| (old, new))
        } else if source.matches(rewrite.pattern.as_str()).count() == 1 {
            Some((rewrite.pattern.clone(), rewrite.replacement.clone()))
        } else {
            changed_lines_edit(&source, &updated)
        };
        if let Some(tool) = tool_for(tool_names, Capability::Edit)
            && let Some((old, new)) = edit
        {
            if result_for_edit(current_turn, &rewrite.target, &old, &new).is_none() {
                return Some(plan_one(tool, edit_arguments(&rewrite.target, &old, &new)));
            }
            return plan_digest_verification(
                task,
                current_turn,
                tool_names,
                &VerifiedChange {
                    target: &rewrite.target,
                    expected: &updated,
                    intent: rewrite.stated_intent(),
                    slots: &rewrite.stated_slots(),
                    list_slots: &[],
                },
                result,
            );
        }
    } else if tool_for(tool_names, Capability::Edit).is_some()
        && let Some(command) = repeated_identifier_rewrite_command(rewrite)
        && let Some(tool) = tool_for(tool_names, Capability::Run)
    {
        if result_for_command(current_turn, &command).is_none() {
            return Some(plan_one(tool, json!({"command": command}).to_string()));
        }
        return plan_digest_verification(
            task,
            current_turn,
            tool_names,
            &VerifiedChange {
                target: &rewrite.target,
                expected: &updated,
                intent: rewrite.stated_intent(),
                slots: &rewrite.stated_slots(),
                list_slots: &[],
            },
            result,
        );
    }

    if result_for_path(
        current_turn,
        Capability::Write,
        &rewrite.target,
        Some(&updated),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(tool, write_arguments(&rewrite.target, &updated)));
    }
    plan_write_digest_verification(
        task,
        current_turn,
        tool_names,
        &VerifiedChange {
            target: &rewrite.target,
            expected: &updated,
            intent: rewrite.stated_intent(),
            slots: &rewrite.stated_slots(),
            list_slots: &[],
        },
        result,
    )
}

fn plan_composite_step(
    task: &str,
    current_turn: &[ChatMessage],
    tool_names: &[&str],
    change: &CompositeModuleChange,
    result: &mut Option<FinalResult>,
) -> Option<AgenticPlan> {
    if result_for_path(
        current_turn,
        Capability::Write,
        &change.source_path,
        Some(&change.source),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            tool,
            write_arguments(&change.source_path, &change.source),
        ));
    }

    let source_command = format!("cat {}", change.source_path);
    let Some(observed_source) = result_for_command(current_turn, &source_command) else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(
            tool,
            json!({"command": source_command}).to_string(),
        ));
    };
    if !super::tool_result::observed_bytes_match(&observed_source, &change.source) {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &change.source_path,
        )?));
    }

    let Some(read) = result_for_path(
        current_turn,
        Capability::Read,
        &change.registration_path,
        None,
    ) else {
        let tool = tool_for(tool_names, Capability::Read)?;
        return Some(plan_one(tool, read_arguments(&change.registration_path)));
    };
    let current = source_from_read_result(&read);
    let updated = insert_registration(&current, &change.registration);
    let registered = ["`", change.registration.trim(), "`"].concat();
    if updated == current {
        return Some(record(
            AgenticPlan::Final(render_seeded_change(
                "coding_member_already_present",
                task,
                &change.registration_path,
                &[("{members}", &registered)],
            )?),
            FinalDisposition::Finding,
            "workspace_change_observed",
            result,
        ));
    }

    if let Some((old, new)) = compact_registration_edit(&current, &change.registration)
        && let Some(tool) = tool_for(tool_names, Capability::Edit)
    {
        if result_for_edit(current_turn, &change.registration_path, &old, &new).is_none() {
            return Some(plan_one(
                tool,
                edit_arguments(&change.registration_path, &old, &new),
            ));
        }
        return plan_digest_verification(
            task,
            current_turn,
            tool_names,
            &VerifiedChange {
                target: &change.registration_path,
                expected: &updated,
                intent: "coding_member_inserted",
                slots: &[("{members}", &registered)],
                list_slots: &[],
            },
            result,
        );
    }

    if result_for_path(
        current_turn,
        Capability::Write,
        &change.registration_path,
        Some(&updated),
    )
    .is_none()
    {
        let tool = tool_for(tool_names, Capability::Write)?;
        return Some(plan_one(
            tool,
            write_arguments(&change.registration_path, &updated),
        ));
    }

    let registration_command = format!("cat {}", change.registration_path);
    let Some(observed_registration) = result_for_command(current_turn, &registration_command)
    else {
        let tool = tool_for(tool_names, Capability::Run)?;
        return Some(plan_one(
            tool,
            json!({"command": registration_command}).to_string(),
        ));
    };
    if !super::tool_result::observed_bytes_match(&observed_registration, &updated) {
        return Some(AgenticPlan::Final(render_seeded_outcome(
            "coding_workspace_verification_failed",
            task,
            &change.registration_path,
        )?));
    }
    Some(record(
        AgenticPlan::Final(render_seeded_change(
            "coding_member_inserted",
            task,
            &change.registration_path,
            &[("{members}", &registered)],
        )?),
        FinalDisposition::Finding,
        "workspace_change_observed",
        result,
    ))
}

/// The file after `rewrite`, or `None` when it cannot apply. A positional
/// insertion replaces its one anchor occurrence; an anchor found zero or
/// several times does not say where the line goes.
/// The rewrite as the request wrote it, when the file holds no unescaped
/// pattern but holds the pattern as written (source code quoting `'\n'`,
/// PR #1188 G65).
fn as_written(source: &str, rewrite: &GroundedRewrite) -> Option<GroundedRewrite> {
    let (pattern, replacement) = rewrite.verbatim.clone()?;
    if (rewrite.pattern != pattern && source.contains(&rewrite.pattern))
        || !source.contains(&pattern)
    {
        return None;
    }
    Some(GroundedRewrite {
        pattern,
        replacement,
        verbatim: None,
        ..rewrite.clone()
    })
}

fn rewritten_source(source: &str, rewrite: &GroundedRewrite) -> Option<String> {
    if rewrite.single_pass {
        return source
            .contains(rewrite.pattern.as_str())
            .then(|| source.replace(rewrite.pattern.as_str(), &rewrite.replacement));
    }
    if rewrite.unique {
        let (start, old, new) = anchored_lines(source, rewrite)?;
        return Some([&source[..start], new.as_str(), &source[start + old.len()..]].concat());
    }
    execute_scoped_workspace_rewrite(
        source,
        &rewrite.pattern,
        &rewrite.replacement,
        rewrite.scope,
    )
    .ok()
    .map(|execution| execution.output)
}

/// A positional insertion's one anchor occurrence widened to the whole lines
/// it sits on, as `(start, old_lines, new_lines)`, or `None` unless the anchor
/// occurs exactly once. The inserted text is a line, so an anchor that is only
/// part of a line (`after the line containing '| T20 |'`) must not split it.
fn anchored_lines(source: &str, rewrite: &GroundedRewrite) -> Option<(usize, String, String)> {
    let (pattern, replacement) = (rewrite.pattern.as_str(), rewrite.replacement.as_str());
    let mut found = source.match_indices(pattern).map(|(at, _)| at);
    let (Some(at), None) = (found.next(), found.next()) else {
        return None;
    };
    let start = source[..at].rfind('\n').map_or(0, |newline| newline + 1);
    let tail = at + pattern.len();
    let end = if pattern.ends_with('\n') {
        tail - 1
    } else {
        source[tail..]
            .find('\n')
            .map_or(source.len(), |newline| tail + newline)
    };
    let old = &source[start..end];
    let new = replacement.strip_prefix(pattern).map_or_else(
        || [&replacement[..replacement.len() - pattern.len()], old].concat(),
        |rest| [old, rest].concat(),
    );
    Some((start, old.to_owned(), new))
}

/// The smallest run of whole lines holding every change from `source` to
/// `updated`, as an edit pair, when that run occurs once in `source`.
pub(super) fn changed_lines_edit(source: &str, updated: &str) -> Option<(String, String)> {
    const MAX_EDIT_BYTES: usize = 4096;
    let prefix = source
        .bytes()
        .zip(updated.bytes())
        .take_while(|(left, right)| left == right)
        .count();
    let limit = source.len().min(updated.len()) - prefix;
    let suffix = source
        .bytes()
        .rev()
        .zip(updated.bytes().rev())
        .take(limit)
        .take_while(|(left, right)| left == right)
        .count();
    // Byte positions only meet `\n`, so `start` and `end` fall on line -- and
    // therefore character -- boundaries even when the first or last differing
    // byte sits inside a multi-byte character.
    let bytes = source.as_bytes();
    let line_start = |before: usize| {
        bytes[..before]
            .iter()
            .rposition(|byte| *byte == b'\n')
            .map_or(0, |at| at + 1)
    };
    let mut start = line_start(prefix);
    let end = bytes[source.len() - suffix..]
        .iter()
        .position(|byte| *byte == b'\n')
        .map_or(source.len(), |at| source.len() - suffix + at);
    // Lines inserted between two lines change none: the line above carries
    // them.
    if start == end && start > 0 {
        start = line_start(start - 1);
    }
    let old = &source[start..end];
    let new = &updated[start..updated.len() - (source.len() - end)];
    (!old.is_empty() && old.len() <= MAX_EDIT_BYTES && source.matches(old).count() == 1)
        .then(|| (old.to_owned(), new.to_owned()))
}

/// `Insert 'x' after the line 'y' in f`: the anchor line, replaced once by the
/// anchor beside the new line, stated by the position meaning that placed it.
fn grounded_positional_insert(task: &str) -> Option<GroundedRewrite> {
    let (target, anchor, replacement) = super::positional_edit::compose_positional_insert(task)?;
    let after_anchor = [anchor.as_str(), "\n"].concat();
    let (after, inserted) = if let Some(inserted) = replacement.strip_prefix(&after_anchor) {
        (true, inserted.to_owned())
    } else {
        let before_anchor = ["\n", anchor.as_str()].concat();
        (false, replacement.strip_suffix(&before_anchor)?.to_owned())
    };
    let intent = super::positional_edit::insert_intent(after, &inserted);
    Some(GroundedRewrite {
        target,
        stated: Some((
            intent,
            vec![(NEW_SLOT, inserted), (ANCHOR_SLOT, anchor.clone())],
        )),
        pattern: anchor,
        replacement,
        scope: RewriteScope::Substring,
        renaming: false,
        unique: true,
        single_pass: false,
        verbatim: None,
    })
}

/// Every insert the request asks for, each its own anchored edit.
///
/// Several clauses (`…, and insert …`), an anchor named by the line it
/// follows (T31, T34), lines rebased on the anchor (G16), or one insert whose
/// anchor is a whole line also found inside others (`the line 'b'`).
fn insert_sequence(task: &str) -> Option<Vec<PositionalInsert>> {
    super::positional_edit::positional_inserts(task)
}

fn grounded_rewrite(task: &str) -> Option<GroundedRewrite> {
    if let Some(positional) = grounded_positional_insert(task) {
        return Some(positional);
    }
    let (target, old_clause, new_clause) = compose_edit_request(task)?;
    let renaming = seed::lexicon().mentions_role(
        seed::ROLE_CODING_IDENTIFIER_RENAME_ACTION,
        &task.to_lowercase(),
    );
    // A request that names a line replaces whole lines
    // (`grounded_line_replacement`).
    if !renaming && super::workspace_computed_change::names_line(task) {
        return None;
    }
    // Both operands have to be literals the request actually quoted, so prose
    // ("replace the old header with something clearer") is never rewritten as
    // bytes. What that cannot be is a count: requiring the request to hold
    // *exactly* two quoted segments made every other pair of delimiters in the
    // prompt disqualify the edit, and this repository's own prose backticks the
    // file it names. The issue #1028 ladder node "In the file
    // `src/protocol_memory.rs`, replace \"request_history\" with
    // \"conversation_history\"" quotes three things and states one replacement.
    // Asking whether each clause *is* quoted keeps the guarantee and drops the
    // arithmetic.
    // The edit request unescapes `\n` / `\t` in its literals, so the quoted
    // segments are compared unescaped too: a multi-line replacement written
    // with `\n` was otherwise not "quoted", and the general fallback wrote its
    // new text over the whole file (PR #1188 sub-agent gap 3).
    let quoted: Vec<String> = quoted_segments(task)
        .iter()
        .map(String::as_str)
        .map(super::positional_edit::unescape_prose_newlines)
        .collect();
    // A literal quoted whole counts even when backtick spans inside it pair
    // among themselves (PR #1188 G63).
    let is_quoted =
        |value: &String| quoted.contains(value) || crate::normal_markov::quotes_whole(task, value);
    let operands = if is_quoted(&old_clause) && is_quoted(&new_clause) {
        Some((old_clause, new_clause))
    } else if renaming {
        Some((
            identifier_tokens(&old_clause).next_back()?.to_owned(),
            identifier_tokens(&new_clause).next()?.to_owned(),
        ))
    } else {
        None
    }?;
    let (old, new) = operands;
    let as_quoted = |text: &str| {
        quoted_segments(task)
            .into_iter()
            .find(|raw| raw != text && super::positional_edit::unescape_prose_newlines(raw) == text)
            .unwrap_or_else(|| text.to_owned())
    };
    let verbatim = (as_quoted(&old) != old || as_quoted(&new) != new)
        .then(|| (as_quoted(&old), as_quoted(&new)));
    // A rename names a *word*, so the edit is word-scoped whichever way the
    // request spelled its operands. Without that scope the most ordinary rename
    // there is -- giving a name a prefix or a suffix -- has to be refused, since
    // an unanchored substring rewrite that reintroduces its own pattern never
    // terminates.
    //
    // A word replaced by a longer word that contains it (`smal` → `small`, a
    // typo fix) is only safe word by word for the same reason.
    let words = is_identifier_word(&old) && is_identifier_word(&new);
    let scope = if words && (renaming || new.contains(&old)) {
        RewriteScope::Word
    } else {
        RewriteScope::Substring
    };
    if old.is_empty() || old == new {
        return None;
    }
    // A new text holding the old one (`key 3` → `key 33`) is replaced in one
    // pass over the file, never rewritten again inside its own result (PR
    // #1188 G78).
    let single_pass = scope == RewriteScope::Substring && new.contains(&old);
    Some(GroundedRewrite {
        target,
        pattern: old,
        replacement: new,
        scope,
        renaming: renaming && scope == RewriteScope::Word,
        unique: false,
        single_pass,
        stated: None,
        verbatim,
    })
}

// This is a seed-template placeholder, not a Rust formatting argument.
#[allow(clippy::literal_string_with_formatting_args)]
fn composite_module_change(task: &str) -> Option<CompositeModuleChange> {
    let lowered = task.to_lowercase();
    if !seed::lexicon().mentions_role(seed::ROLE_CODING_MODULE_REGISTRATION_ACTION, &lowered) {
        return None;
    }
    let generated = rust_source_for_task(task)?;
    let registration_path = rust_paths(task)
        .into_iter()
        .find(|path| path != &generated.path)?;
    let module = generated.path.rsplit('/').next()?.strip_suffix(".rs")?;
    if !valid_identifier(module) {
        return None;
    }
    let registration =
        render_rust_template("coding_source_module_registration", &[("{module}", module)])?;
    Some(CompositeModuleChange {
        source_path: generated.path,
        source: generated.content,
        registration_path,
        registration,
    })
}

fn insert_registration(source: &str, registration: &str) -> String {
    if source
        .lines()
        .any(|line| line.trim() == registration.trim())
    {
        return source.to_owned();
    }
    let mut updated = source.to_owned();
    if !updated.is_empty() && !updated.ends_with('\n') {
        updated.push('\n');
    }
    updated.push_str(registration);
    updated
}

fn compact_registration_edit(source: &str, registration: &str) -> Option<(String, String)> {
    const MAX_SUFFIX_BYTES: usize = 4096;
    let mut starts = source
        .match_indices('\n')
        .map(|(index, _)| index + 1)
        .filter(|start| *start < source.len())
        .collect::<Vec<_>>();
    starts.insert(0, 0);
    for start in starts.into_iter().rev() {
        let suffix = &source[start..];
        if suffix.len() > MAX_SUFFIX_BYTES {
            break;
        }
        if source.match_indices(suffix).count() != 1 {
            continue;
        }
        let mut replacement = suffix.to_owned();
        if !replacement.ends_with('\n') {
            replacement.push('\n');
        }
        replacement.push_str(registration);
        return Some((suffix.to_owned(), replacement));
    }
    None
}

fn repeated_identifier_rewrite_command(rewrite: &GroundedRewrite) -> Option<String> {
    if !shell_safe_identifier(&rewrite.pattern) || !shell_safe_identifier(&rewrite.replacement) {
        return None;
    }
    // The in-memory execution and the command the client runs have to agree on
    // what a match is, so a word-scoped rewrite asks for whole words too.
    let pattern = match rewrite.scope {
        RewriteScope::Substring => rewrite.pattern.clone(),
        RewriteScope::Word => format!("\\b{}\\b", rewrite.pattern),
    };
    // `perl -pi -e`, not `sed -i` (issue #1110). GNU and BSD sed disagree about
    // both halves of that command: BSD `-i` reads the script as its backup
    // suffix, and BSD sed has no `\b`. On macOS every rename therefore failed
    // with `bad flag in substitute command`, the file was left unchanged, and
    // Formal AI reported the mismatch as its own verification failure -- a
    // confident failure report instead of a rename. perl's `-pi -e` and `\b`
    // mean the same thing on both, and perl ships with macOS and the runners.
    // Both identifiers are `[A-Za-z0-9_]` by `shell_safe_identifier`, so
    // neither side can carry a regex or shell metacharacter.
    // Assembled from named parts rather than one template string: the prose
    // detector reads `perl -pi -e ...` as a multi-word phrase (two alphabetic
    // runs, one of three letters) and would have it live in `data/seed`, which
    // is the wrong home for a shell invocation. Naming the pieces says what
    // each is, and none of them reads as a sentence.
    let script = format!("'s/{pattern}/{}/g'", rewrite.replacement);
    Some(["perl", "-pi", "-e", &script, "--", &rewrite.target].join(" "))
}

fn shell_safe_identifier(identifier: &str) -> bool {
    !identifier.is_empty()
        && identifier
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || character == '_')
}

pub(super) fn identifier_tokens(text: &str) -> impl DoubleEndedIterator<Item = &str> {
    text.split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
        .filter(|token| valid_identifier(token))
}

fn valid_identifier(identifier: &str) -> bool {
    let mut characters = identifier.chars();
    characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && characters.all(|character| character.is_ascii_alphanumeric() || character == '_')
        && !seed::lexicon()
            .words_for_role(seed::ROLE_IDENTIFIER_RESERVED_WORD)
            .iter()
            .any(|reserved| reserved == identifier)
}

fn rust_paths(task: &str) -> Vec<String> {
    let mut paths = Vec::new();
    for (suffix, _) in task.match_indices(".rs") {
        let end = suffix + 3;
        let start = task[..end]
            .char_indices()
            .rev()
            .take_while(|(_, character)| {
                character.is_ascii_alphanumeric() || matches!(character, '_' | '-' | '.' | '/')
            })
            .last()
            .map_or(0, |(index, _)| index);
        let path = &task[start..end];
        if !path.is_empty()
            && !path.starts_with('/')
            && !path.split('/').any(|component| component == "..")
            && !paths.iter().any(|existing| existing == path)
        {
            paths.push(path.to_owned());
        }
    }
    paths
}

pub(super) fn result_for_path(
    messages: &[ChatMessage],
    capability: Capability,
    path: &str,
    expected_content: Option<&str>,
) -> Option<String> {
    matching_result(messages, |name, arguments| {
        if tool_capability(name) != Some(capability) {
            return false;
        }
        let Ok(value) = serde_json::from_str::<Value>(arguments) else {
            return false;
        };
        let matches_path = ["path", "filePath", "file_path"].iter().any(|key| {
            value
                .get(key)
                .and_then(Value::as_str)
                .is_some_and(|observed| workspace_path_matches(path, observed))
        });
        matches_path
            && expected_content.is_none_or(|expected| {
                value.get("content").and_then(Value::as_str) == Some(expected)
            })
    })
}

pub(super) fn result_for_edit(
    messages: &[ChatMessage],
    path: &str,
    old: &str,
    new: &str,
) -> Option<String> {
    matching_result(messages, |name, arguments| {
        if tool_capability(name) != Some(Capability::Edit) {
            return false;
        }
        let Ok(value) = serde_json::from_str::<Value>(arguments) else {
            return false;
        };
        argument_matches_path(&value, path)
            && argument_matches(&value, &["oldString", "old_string", "old_str", "old"], old)
            && argument_matches(&value, &["newString", "new_string", "new_str", "new"], new)
    })
}

fn argument_matches_path(value: &Value, expected: &str) -> bool {
    ["path", "filePath", "file_path"].iter().any(|key| {
        value
            .get(key)
            .and_then(Value::as_str)
            .is_some_and(|observed| workspace_path_matches(expected, observed))
    })
}

fn argument_matches(value: &Value, keys: &[&str], expected: &str) -> bool {
    keys.iter()
        .any(|key| value.get(key).and_then(Value::as_str) == Some(expected))
}

fn workspace_path_matches(expected: &str, observed: &str) -> bool {
    if observed == expected {
        return true;
    }
    let expected = Path::new(expected);
    let observed = Path::new(observed);
    expected.is_relative() && observed.is_absolute() && observed.ends_with(expected)
}

pub(super) fn result_for_command(messages: &[ChatMessage], command: &str) -> Option<String> {
    super::code_artifact::result_for_command(messages, command)
}

fn matching_result(
    messages: &[ChatMessage],
    matches: impl Fn(&str, &str) -> bool,
) -> Option<String> {
    messages
        .iter()
        .enumerate()
        .rev()
        .find_map(|(index, message)| {
            if !message.role.eq_ignore_ascii_case("tool") {
                return None;
            }
            let id = message.tool_call_id.as_deref()?;
            let call = messages[..index]
                .iter()
                .rev()
                .flat_map(|prior| prior.tool_calls.iter().rev())
                .find(|call| call.id == id)?;
            matches(&call.function.name, &call.function.arguments)
                .then(|| message.content.plain_text())
        })
}

pub(super) fn read_arguments(path: &str) -> String {
    json!({"path": path, "filePath": path, "file_path": path}).to_string()
}

changes.expected:
//! Grounded, verified workspace transformations learned from coding-task runs.
//!
//! The planner never edits request prose. It compiles a bounded transformation,
//! reads the client-owned bytes, executes the transformation in memory, applies
//! a compact edit or bounded replace-all operation, and accepts success only
//! after an exact content-digest observation. The same state machine composes
//! source creation with a second module-registration edit, so a multi-file
//! request cannot stop after its first observable effect.

mod digest_verification;
pub(super) use digest_verification::{plan_digest_verification, plan_write_digest_verification};

use serde_json::{Value, json};
use std::path::Path;

use super::code_artifact::source_from_read_result;
use super::code_task::{
    render_rust_template, render_seeded_change, render_seeded_outcome, rust_source_for_task,
};
use super::final_result::{FinalDisposition, FinalResult, record};
